// Checks the uploaded photo and reads the form.
const item = $input.first();
const files = item.binary || {};
const key = Object.keys(files)[0];
if (!key) throw new Error('Add a product photo to the form.');
const buffer = await this.helpers.getBinaryDataBuffer(0, key);
if (buffer.length > 10 * 1024 * 1024) throw new Error('The photo is bigger than 10 MB. Use a smaller photo.');
if (!/^image\/(png|jpe?g|webp)$/.test(files[key].mimeType || '')) throw new Error('Use a JPG, PNG or WebP photo.');
const form = item.json;
const product = String(form['Product name'] || '').trim();
const brief = String(form['Who is it for, and why do they buy it?'] || '').trim();
if (!product || !brief) throw new Error('Fill in the product name and who it is for.');
return [{ json: { product, brief }, binary: { photo: files[key] } }];

