// One item per ad image: every angle in every size.
const reply = $input.first().json;
const said = String(reply.choices?.[0]?.message?.content || '');
const found = said.match(/\{[\s\S]*\}/);
let plan;
try { plan = JSON.parse(found ? found[0] : said); } catch (e) {
  throw new Error('The copy model did not answer in the expected shape. Send the form again, or pick another copy_model in Settings.');
}
const s = $('Settings').first().json;
const text = (v) => String(v ?? '').trim();
const count = Math.max(1, Math.min(10, Number(s.angles) || 5));
const variants = (Array.isArray(plan.variants) ? plan.variants : []).filter((v) => text(v?.headline) && text(v?.image_prompt)).slice(0, count);
if (!variants.length) throw new Error('The copy model wrote no usable angles. Send the form again.');
const sizes = [...new Set(text(s.ad_sizes).split(',').map((x) => x.trim()).filter(Boolean))];
if (!sizes.length) throw new Error('Settings: write at least one size in ad_sizes, for example 1:1, 4:5, 9:16.');
const form = $('Get the photo ready').first().json;
const photo = $('Save the photo').first().json;
if (!photo.url && !photo.id) throw new Error('The photo was not saved: ' + (photo.error?.message || 'no file came back') + '.');
const backups = text(s.backup_image_models).split(',').map((x) => x.trim()).filter(Boolean);
const budget = Number(s.max_total_cost_usd) || 1;
const safe = (v) => text(v).replace(/[^\p{L}\p{N} _-]+/gu, ' ').replace(/\s+/g, ' ').trim().slice(0, 40);
const ads = [];
variants.forEach((v, i) => sizes.forEach((size) => ads.push({ json: {
  product: form.product, variant: i + 1, angle: text(v.angle) || 'Angle ' + (i + 1), headline: text(v.headline).slice(0, 80), primary_text: text(v.primary_text).slice(0, 300), size,
  file_name: (safe(form.product) || 'ad') + ' v' + (i + 1) + ' ' + size.replace(':', 'x'),
  copy_cost_usd: Number(reply.usage?.cost_usd) || 0,
  backups,
  request: {
    model: s.image_model,
    prompt: text(v.image_prompt).replace(/[.\s]+$/, '') + '. The product is ' + form.product + '. Keep the product exactly as it is in the photo: same shape, colours, label and text. Realistic advertising photo. Do not add text, logos or prices.',
    image_url: photo.url || photo.id, aspect_ratio: size, max_cost: budget,
    metadata: { template: 'ad-creative-test-set', variant: String(i + 1), size },
  },
} })));
return ads;

// Stops before anything is made when an image is refused or the set would cost too much.
const ads = $('Read the angles').all();
const quotes = $input.all().map((i) => i.json);
const s = $('Settings').first().json;
const bad = quotes.findIndex((q) => q.valid !== true);
if (bad >= 0) {
  const q = quotes[bad];
  throw new Error('Size ' + ads[bad].json.size + ' cannot be made: ' + (q.error?.message || (typeof q.error === 'string' ? q.error : '') || q.message || 'the price check did not answer') + ' Nothing was made and nothing was charged.');
}
const total = Math.round(quotes.reduce((sum, q) => sum + Number(q.cost_usd || 0), 0) * 1e6) / 1e6;
const budget = Number(s.max_total_cost_usd) || 1;
if (total > budget) throw new Error(ads.length + ' images would cost about $' + total + ', more than max_total_cost_usd in Settings ($' + budget + '). Lower angles or ad_sizes, or raise the limit. Nothing was made and nothing was charged.');
const stamp = new Date().toISOString().slice(0, 16).replace('T', ' ');
return [{ json: { images: ads.length, quoted_total_usd: total, folder_name: ads[0].json.product + ' ad test ' + stamp } }];

// The ads again, one item each, now that the price is fine and the folder exists.
const folder = $input.first().json;
if (!folder.id) throw new Error('Google Drive did not make the folder. Check the Google Drive credential.');
return $('Read the angles').all().map((ad) => {
  const { backups, ...rest } = ad.json;
  return { json: { ...rest, folder_id: folder.id, request: { ...rest.request, models: backups } } };
});

// What this run made. The same numbers are in the sheet, one row per image.
const rows = $input.all().map((i) => i.json).filter((r) => r.status !== undefined);
const made = rows.filter((r) => r.status === 'made');
const first = $('Ads to make').first().json;
const cost = made.reduce((sum, r) => sum + (Number(r.cost_usd) || 0), 0) + (Number(first.copy_cost_usd) || 0);
const failed = rows.find((r) => r.status !== 'made');
return [{ json: {
  images_made: made.length,
  images_not_made: rows.length - made.length,
  total_cost_usd: Math.round(cost * 1e6) / 1e6,
  folder_link: 'https://drive.google.com/drive/folders/' + first.folder_id,
  first_problem: failed ? failed.status : '',
} }];
